import Foundation
import MurmurKit

// Cleanup-fidelity benchmark. Runs the app's exact post-STT pipeline
// (corrector -> Cleaner -> corrector, with the user's real config vocabulary)
// over a fixture corpus against a private llama-server, and scores:
//   exact   : normalized tokens equal an accepted expected output
//   wer     : token edit distance to the closest expected / its length
//   novel   : output tokens absent from the input AND every expected (invented words = rewriting)
//   dropped : tokens of the closest expected missing from the output (content lost)
//
// usage: Bench <model.gguf|none> <label> [port] [corpus.json]

struct Case: Decodable { let id: String; let cat: String; let input: String; let expected: [String] }

func tokens(_ s: String) -> [String] {
    let lowered = s.lowercased().replacingOccurrences(of: "\u{2019}", with: "'")
    var out: [String] = []
    var cur = ""
    for ch in lowered {
        if ch.isLetter || ch.isNumber || ch == "'" { cur.append(ch) } else {
            if !cur.isEmpty { out.append(cur) }
            cur = ""
        }
    }
    if !cur.isEmpty { out.append(cur) }
    return out.map { $0.trimmingCharacters(in: CharacterSet(charactersIn: "'")) }.filter { !$0.isEmpty }
}

func editDistance(_ a: [String], _ b: [String]) -> Int {
    if a.isEmpty { return b.count }
    if b.isEmpty { return a.count }
    var prev = Array(0...b.count)
    for i in 1...a.count {
        var cur = [i] + Array(repeating: 0, count: b.count)
        for j in 1...b.count {
            cur[j] = min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] == b[j - 1] ? 0 : 1))
        }
        prev = cur
    }
    return prev[b.count]
}

func lcs(_ a: [String], _ b: [String]) -> Int {
    if a.isEmpty || b.isEmpty { return 0 }
    var prev = Array(repeating: 0, count: b.count + 1)
    for i in 1...a.count {
        var cur = Array(repeating: 0, count: b.count + 1)
        for j in 1...b.count {
            cur[j] = a[i - 1] == b[j - 1] ? prev[j - 1] + 1 : max(prev[j], cur[j - 1])
        }
        prev = cur
    }
    return prev[b.count]
}

