let kind = args[2]
let rounds = Int(args[3]) ?? 5
let wavs = Array(args[4...])
let defaults = Config()
func expand(_ p: String) -> String { (p as NSString).expandingTildeInPath }

let engine: TranscriptionEngine & LocalServerEngine
switch kind {
case "qwen17":
    engine = QwenAsrEngine(binaryPath: cfg.llamaBinaryPath, modelPath: cfg.qwenAsrModelPath,
                           mmprojPath: cfg.qwenAsrMmprojPath, port: 18_927, language: cfg.language)
case "qwen06":
    engine = QwenAsrEngine(binaryPath: cfg.llamaBinaryPath, modelPath: defaults.qwenAsrModelPath,
                           mmprojPath: defaults.qwenAsrMmprojPath, port: 18_928, language: cfg.language)
case "whisper":
    engine = WhisperCppEngine(binaryPath: cfg.whisperBinaryPath, modelPath: cfg.whisperModelPath,
                              port: 18_923, language: cfg.language)
case "parakeet":
    engine = ParakeetEngine(binaryPath: expand(cfg.parakeetBinaryPath),
                            modelPath: expand(cfg.parakeetModelPath), port: 18_926)
default:
    print("unknown engine \(kind)"); exit(2)
}
let chat = LlamaCppChatEngine(binaryPath: cfg.llamaBinaryPath, modelPath: cfg.llamaModelPath, port: 18_825)
let cleaner = Cleaner(chat: chat, vocabulary: cfg.cleanupVocabulary)
let corrector = TranscriptCorrector(terms: cfg.cleanupVocabulary, aliases: cfg.effectiveAliases)
let prompt = VocabularyPrompt.whisperPrompt(cfg.vocabulary(for: .general))

do {
    try await chat.ensureReady()
    let silence = WAVEncoder.encode(samples: [Int16](repeating: 0, count: 16_000), sampleRate: 16_000)
    _ = try await engine.transcribe(wav: silence, prompt: prompt)
    let first = try Data(contentsOf: URL(fileURLWithPath: wavs[0]))
    let warm = try await engine.transcribe(wav: first, prompt: prompt)
    _ = await cleaner.cleanOrFallback(corrector.correct(warm))
    for round in 0..<rounds {
        for path in (round % 2 == 0 ? wavs : wavs.reversed()) {
            let wav = try Data(contentsOf: URL(fileURLWithPath: path))
            let t0 = Date()
            let raw = try await engine.transcribe(wav: wav, prompt: prompt)
            let t1 = Date()
            let corrected = corrector.correct(raw)
            let cleaned = await cleaner.cleanOrFallback(corrected)
            let text = corrector.correct(cleaned)
            let t2 = Date()
            let row: [String: Any] = [
                "engine": kind, "round": round, "wav": (path as NSString).lastPathComponent,
                "audio": Double(max(0, wav.count - 44)) / 32_000,
                "stt": t1.timeIntervalSince(t0), "cleanup": t2.timeIntervalSince(t1),
                "total": t2.timeIntervalSince(t0), "words": raw.split(separator: " ").count,
                "cleanup_changed": cleaned != corrected.trimmingCharacters(in: .whitespacesAndNewlines),
                "text": text,
            ]
            print(String(decoding: try JSONSerialization.data(withJSONObject: row, options: [.sortedKeys]),
                         as: UTF8.self))
            fflush(stdout)
        }
    }
} catch {
    print("error: \(error)")
}
engine.shutdown()
chat.shutdown()
exit(0)
