// fcache [-e] file...: prints how much of each file sits in the page cache
// (mincore); -e first evicts the file's clean cached pages (msync
// MS_INVALIDATE, as vmtouch -e does on macOS). Read-only: nothing is written.
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

static double resident_mb(void *p, size_t len, size_t page) {
    size_t pages = (len + page - 1) / page, hit = 0;
    char *vec = malloc(pages);
    if (!vec || mincore(p, len, vec) != 0) { free(vec); return -1; }
    for (size_t i = 0; i < pages; i++) hit += (vec[i] & 1);
    free(vec);
    return (double)hit * page / 1048576.0;
}

int main(int argc, char **argv) {
    int evict = 0, first = 1;
    if (argc > 1 && strcmp(argv[1], "-e") == 0) { evict = 1; first = 2; }
    size_t page = (size_t)getpagesize();
    for (int i = first; i < argc; i++) {
        int fd = open(argv[i], O_RDONLY);
        struct stat st;
        if (fd < 0 || fstat(fd, &st) != 0) { perror(argv[i]); return 1; }
        void *p = mmap(NULL, (size_t)st.st_size, PROT_READ, MAP_SHARED, fd, 0);
        if (p == MAP_FAILED) { perror("mmap"); return 1; }
        double before = resident_mb(p, (size_t)st.st_size, page);
        int rc = 0;
        if (evict) rc = msync(p, (size_t)st.st_size, MS_INVALIDATE);
        double after = resident_mb(p, (size_t)st.st_size, page);
        printf("%s: size %.0f MB, cached %.0f MB%s", strrchr(argv[i], '/') ? strrchr(argv[i], '/') + 1 : argv[i],
               st.st_size / 1048576.0, before, evict ? "" : "\n");
        if (evict) printf(" -> evict rc=%d -> cached %.0f MB\n", rc, after);
        munmap(p, (size_t)st.st_size);
        close(fd);
    }
    return 0;
}
EOF
