// ra_modes <mode> <chunkMiB> <holdSeconds> file: read-ahead variants.
// mode "advise": fcntl F_RDADVISE in chunkMiB pieces; "read": pread() the
// whole file through a 4 MiB buffer. Keeps the fd open holdSeconds after.
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>
static double now(void) { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return t.tv_sec + t.tv_nsec / 1e9; }
int main(int argc, char **argv) {
    if (argc != 5) { fprintf(stderr, "usage\n"); return 2; }
    off_t chunk = (off_t)atoll(argv[2]) << 20;
    int fd = open(argv[4], O_RDONLY);
    struct stat st;
    if (fd < 0 || fstat(fd, &st) != 0) { perror("open"); return 1; }
    double t0 = now();
    int calls = 0, failures = 0;
    if (strcmp(argv[1], "advise") == 0) {
        for (off_t off = 0; off < st.st_size; off += chunk) {
            struct radvisory ra = { .ra_offset = off, .ra_count = (int)((st.st_size - off) < chunk ? (st.st_size - off) : chunk) };
            calls++;
            if (fcntl(fd, F_RDADVISE, &ra) != 0) failures++;
        }
    } else {
        size_t n = 4 << 20;
        char *buf = malloc(n);
        for (off_t off = 0; off < st.st_size; off += n) { calls++; if (pread(fd, buf, n, off) < 0) failures++; }
        free(buf);
    }
    printf("%s chunk %s MiB: %d calls, %d failed, returned in %.0f ms\n", argv[1], argv[2], calls, failures, (now() - t0) * 1000);
    fflush(stdout);
    sleep((unsigned)atoi(argv[3]));
    close(fd);
    return 0;
}
EOF
